export const getTp02ThreeInOneContent = (product?: Pick<Product, 'name' | 'slug' | 'specs'> | null) => {
  if (!product) return null;
  const identifiers = [product.name, product.specs?.Model, product.specs?.['Model Number'], product.slug?.replace(/-/g, ' ')].filter(Boolean).join(' ');
  const isThreeInOne = /\btp\s*-?\s*02\b/i.test(identifiers) && /3\s*-?\s*in\s*-?\s*1\b/i.test(identifiers);
  return isThreeInOne || product.slug === 'tfx-pureair-3-in-1' ? TP02_THREE_IN_ONE_CONTENT : null;
};

